create or replace function public.admin_set_profile(p_user_id uuid,p_display_name text,p_role public.bank_role,p_status text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'Administrator access required'; end if; if p_status not in ('pending','active','suspended') then raise exception 'Invalid profile status'; end if; update public.profiles set display_name=left(coalesce(p_display_name,''),100),role=p_role,status=p_status,updated_at=now() where id=p_user_id; if not found then raise exception 'Profile not found'; end if; insert into public.audit_events(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'profile_updated','profile',p_user_id::text,jsonb_build_object('role',p_role,'status',p_status)); end $$;
create or replace function public.admin_create_account(p_name text,p_kind public.account_kind,p_user_id uuid default null) returns public.bank_accounts language plpgsql security definer set search_path=public as $$ declare a public.bank_accounts; perm text; begin if not public.is_admin() then raise exception 'Administrator access required'; end if; if length(trim(coalesce(p_name,'')))=0 then raise exception 'Account name is required'; end if; if p_kind='treasury' and p_user_id is not null then raise exception 'Treasury accounts cannot have personal members'; end if; insert into public.bank_accounts(name,kind,status,created_by) values(left(trim(p_name),100),p_kind,'active',auth.uid()) returning * into a; if p_user_id is not null then perm:=case when p_kind='corporate' then 'manage' else 'operate' end; insert into public.account_memberships(account_id,user_id,permission) values(a.id,p_user_id,perm); end if; insert into public.audit_events(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'account_created','account',a.id::text,jsonb_build_object('kind',p_kind,'name',a.name)); return a; end $$;
create or replace function public.admin_add_account_member(p_account_id uuid,p_user_id uuid,p_permission text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'Administrator access required'; end if; if p_permission not in ('view','operate','manage') then raise exception 'Invalid permission'; end if; insert into public.account_memberships(account_id,user_id,permission) values(p_account_id,p_user_id,p_permission) on conflict(account_id,user_id) do update set permission=excluded.permission; insert into public.audit_events(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'account_member_assigned','account',p_account_id::text,jsonb_build_object('user_id',p_user_id,'permission',p_permission)); end $$;
create or replace function public.admin_issue_cheque_book(p_account_id uuid,p_book_size integer) returns public.cheque_books language plpgsql security definer set search_path=public as $$ declare a public.bank_accounts; b public.cheque_books; prefix text; begin if not public.is_admin() then raise exception 'Administrator access required'; end if; select * into a from public.bank_accounts where id=p_account_id for update; if not found or a.kind='treasury' then raise exception 'A personal or corporate account is required'; end if; if (a.kind='personal' and p_book_size<>30) or (a.kind='corporate' and p_book_size<>150) then raise exception 'Personal books contain 30 cheques; corporate books contain 150'; end if; prefix:='BR'||upper(substr(encode(gen_random_bytes(5),'hex'),1,8)); insert into public.cheque_books(account_id,book_size,serial_prefix,issued_by) values(p_account_id,p_book_size,prefix,auth.uid()) returning * into b; insert into public.audit_events(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'cheque_book_issued','cheque_book',b.id::text,jsonb_build_object('size',p_book_size,'prefix',prefix)); return b; end $$;
create or replace function public.admin_post_transfer(p_debit uuid,p_credit uuid,p_amount numeric,p_description text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path=public as $$ declare tx uuid; begin if not public.is_admin() then raise exception 'Administrator access required'; end if; if length(coalesce(p_idempotency_key,''))<8 then raise exception 'A unique idempotency key is required'; end if; tx:=public.post_ledger_transaction(left(p_description,160),p_debit,p_credit,p_amount,p_idempotency_key); insert into public.audit_events(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'admin_transfer_posted','ledger_transaction',tx::text,jsonb_build_object('amount',p_amount,'debit',p_debit,'credit',p_credit)); return tx; end $$;
create or replace function public.admin_add_holiday(p_date date,p_name text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'Administrator access required'; end if; insert into public.bank_holidays(holiday_date,name) values(p_date,left(p_name,100)) on conflict(holiday_date) do update set name=excluded.name; insert into public.audit_events(actor_id,action,target_type,target_id) values(auth.uid(),'bank_holiday_updated','bank_holiday',p_date::text); end $$;
create or replace function public.admin_record_allocation(p_account_id uuid,p_treasury_id uuid,p_pilot_count integer,p_fleet_count integer,p_route_count integer,p_amount numeric,p_notes text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path=public as $$ declare tx uuid; begin if not public.is_admin() then raise exception 'Administrator access required'; end if; if not exists(select 1 from public.bank_accounts where id=p_account_id and kind='corporate' and status='active') then raise exception 'An active corporate account is required'; end if; if not exists(select 1 from public.bank_accounts where id=p_treasury_id and kind='treasury' and status='active') then raise exception 'An active treasury account is required'; end if; insert into public.allocation_runs(airline_account_id,pilot_count,fleet_count,route_count,amount,notes,created_by) values(p_account_id,p_pilot_count,p_fleet_count,p_route_count,p_amount,left(p_notes,500),auth.uid()); tx:=public.post_ledger_transaction('Airline capital allocation',p_treasury_id,p_account_id,p_amount,p_idempotency_key); insert into public.audit_events(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'airline_allocation_recorded','account',p_account_id::text,jsonb_build_object('pilots',p_pilot_count,'fleet',p_fleet_count,'routes',p_route_count,'amount',p_amount)); return tx; end $$;
grant execute on function public.admin_set_profile(uuid,text,public.bank_role,text),public.admin_create_account(text,public.account_kind,uuid),public.admin_add_account_member(uuid,uuid,text),public.admin_issue_cheque_book(uuid,integer),public.admin_post_transfer(uuid,uuid,numeric,text,text),public.admin_add_holiday(date,text),public.admin_record_allocation(uuid,uuid,integer,integer,integer,numeric,text,text) to authenticated;
